#!/bin/sh
# Generated by synth_containers.harbor_translation. Runs on an admitted build
# host only; Rust dependency resolution goes through mbx, never raw cargo.
set -eu
root="$SYNTH_CONTAINER_PACKAGE_ROOT"
platform=linux/amd64
CARGO_HOME="$root/context/.synth-cargo-home" mbx fetch --manifest-path "$root/context/harness/Cargo.toml"
docker build --platform "$platform" --file "$root/Dockerfile" --iidfile "$root/.image-id" "$root/context"
python3 -I - "$SYNTH_CONTAINER_BUILD_PLAN" "$root/.image-id" "$platform" "$SYNTH_CONTAINER_BUILD_OUTPUT" <<'PY'
import json, sys
plan = json.load(open(sys.argv[1]))
image = open(sys.argv[2]).read().strip()
json.dump({'schema_version': 'synth.container-build-output.v1', 'action': 'build',
           'input_digest': plan['input_digest'], 'artifact': {'kind': 'oci_image',
           'digest_kind': 'oci_config', 'reference': image, 'digest': image,
           'platform': sys.argv[3]}}, open(sys.argv[4], 'w'))
PY
